import json
import unittest
from pathlib import Path

import main


BASELINE_DIR = Path(__file__).parent / 'baseline'
SEQUENCIAS = {
    'seq1': 'Bm,G,D,A',
    'seq2': 'C,G,Am,F',
    'seq3': 'Gm,F',
    'seq4': 'C,C7,F,Fm',
    'seq5': 'Em,G',
    'seq6': 'C,A7,Dm,G7',
}


class RegressaoSequenciasTest(unittest.TestCase):

    @classmethod
    def setUpClass(cls):
        main.app.config['TESTING'] = True
        cls.client = main.app.test_client()

    def buscar(self, parametros):
        musicas = set()
        pagina = 1
        while pagina <= 1000:
            query = dict(parametros)
            query['pagina'] = str(pagina)
            resposta = self.client.get('/similares', query_string=query)
            self.assertEqual(resposta.status_code, 200)
            dados = json.loads(resposta.data)
            if not dados:
                return musicas
            musicas.update(m['id_unico_musica'] for m in dados)
            pagina += 1
        self.fail('paginação não terminou para %r' % (parametros,))

    def baseline(self, nome):
        with open(BASELINE_DIR / ('%s.json' % nome)) as arquivo:
            return set(json.load(arquivo))

    def test_parametro_legado_reproduz_baseline(self):
        for nome, sequencia in SEQUENCIAS.items():
            with self.subTest(sequencia=sequencia):
                self.assertEqual(
                    self.buscar({'sequencia': sequencia}),
                    self.baseline(nome),
                )


if __name__ == '__main__':
    unittest.main()

import unittest

import main


ROTAS_EXPLICITAS = {
    '/',
    '/acordes',
    '/generos',
    '/musica/<m_id>/',
    '/musicas',
    '/search',
    '/similares',
    '/static/<path:filename>',
}

VERBOS_NO_PATH = (
    '/cadastra',
    '/lista',
    '/remove',
    '/deleta',
    '/exclui',
    '/atualiza',
    '/edita',
)


class InventarioDeRotasTest(unittest.TestCase):

    def regras_relevantes(self):
        for regra in main.app.url_map.iter_rules():
            if regra.rule == '/<path:path>':
                continue
            metodos = set(regra.methods) - {'HEAD', 'OPTIONS'}
            yield regra, metodos

    def test_sem_verbos_no_path(self):
        for regra, _ in self.regras_relevantes():
            for verbo in VERBOS_NO_PATH:
                with self.subTest(rota=regra.rule):
                    self.assertNotIn(verbo, regra.rule)

    def test_sem_metodos_de_mutacao_inesperados(self):
        for regra, metodos in self.regras_relevantes():
            with self.subTest(rota=regra.rule):
                self.assertFalse(metodos & {'DELETE', 'PUT', 'PATCH'})
                self.assertTrue(metodos <= {'GET', 'POST'})

    def test_somente_rotas_esperadas(self):
        rotas = {regra.rule for regra, _ in self.regras_relevantes()}
        self.assertEqual(rotas, ROTAS_EXPLICITAS)


if __name__ == '__main__':
    unittest.main()

