import json
import unittest
from pathlib import Path

import main
from matching import (
    calcular_matches,
    lista_canonica,
    normalizar_acordes,
    sequencia_aparece,
)


BASELINE_DIR = Path(__file__).parent / 'baseline'
SEQUENCIAS_BASELINE = {
    'seq1': ['Bm', 'G', 'D', 'A'],
    'seq2': ['C', 'G', 'Am', 'F'],
    'seq3': ['Gm', 'F'],
    'seq4': ['C', 'C7', 'F', 'Fm'],
    'seq5': ['Em', 'G'],
    'seq6': ['C', 'A7', 'Dm', 'G7'],
}


class NormalizacaoTest(unittest.TestCase):

    def test_string_com_virgula_e_ponto_e_virgula(self):
        self.assertEqual(
            normalizar_acordes(' Bm, G ; D ,A '),
            ['Bm', 'G', 'D', 'A'],
        )

    def test_lista_com_espacos_e_vazios(self):
        self.assertEqual(
            normalizar_acordes([' Bm', 'G ', '', '  ', 'A']),
            ['Bm', 'G', 'A'],
        )

    def test_preserva_caixa(self):
        self.assertEqual(normalizar_acordes('7M,7m'), ['7M', '7m'])

    def test_lista_canonica(self):
        self.assertEqual(lista_canonica(['Bm', 'G']), '["Bm","G"]')


class RegraDeMatchingTest(unittest.TestCase):

    def test_bloco_contiguo_e_ordenado(self):
        self.assertTrue(
            sequencia_aparece(['Bm', 'G', 'D', 'A'], ['Bm', 'G', 'D', 'A'])
        )

    def test_bloco_em_outra_posicao(self):
        self.assertTrue(
            sequencia_aparece(
                ['E', 'Bm', 'G', 'D', 'A'], ['Bm', 'G', 'D', 'A']
            )
        )

    def test_ordem_diferente_nao_casa(self):
        self.assertFalse(
            sequencia_aparece(['G', 'Bm', 'D', 'A'], ['Bm', 'G', 'D', 'A'])
        )

    def test_acorde_fora_da_sequencia_nao_casa(self):
        self.assertFalse(
            sequencia_aparece(['Bm', 'G', 'D', 'A', 'E'], ['Bm', 'G', 'D', 'A'])
        )

    def test_musica_sem_cifra_nao_casa(self):
        self.assertFalse(sequencia_aparece([], ['Bm', 'G']))

    def test_caixa_preservada(self):
        self.assertFalse(sequencia_aparece(['C7M'], ['C7m']))
        self.assertTrue(sequencia_aparece(['C7M'], ['C7M']))

    def test_repeticao_antes_do_bloco_e_permitida(self):
        self.assertTrue(
            sequencia_aparece(
                ['Bm', 'Bm', 'G', 'D', 'A'], ['Bm', 'G', 'D', 'A']
            )
        )

    def test_repeticao_dentro_do_bloco_quebra(self):
        self.assertFalse(
            sequencia_aparece(
                ['Bm', 'G', 'G', 'D', 'A'], ['Bm', 'G', 'D', 'A']
            )
        )

    def test_repeticao_fora_do_bloco_e_permitida(self):
        self.assertTrue(
            sequencia_aparece(
                ['Bm', 'G', 'D', 'A', 'Bm'], ['Bm', 'G', 'D', 'A']
            )
        )

    def test_sequencia_com_repeticao_exige_bloco_repetido(self):
        self.assertFalse(
            sequencia_aparece(['Bm', 'G', 'D', 'A'], ['Bm', 'Bm', 'G', 'D', 'A'])
        )
        self.assertTrue(
            sequencia_aparece(
                ['Bm', 'Bm', 'G', 'D', 'A'], ['Bm', 'Bm', 'G', 'D', 'A']
            )
        )


class RegressaoDoAlgoritmoTest(unittest.TestCase):

    def test_as_seis_sequencias_reproduzem_o_baseline(self):
        for nome, acordes in SEQUENCIAS_BASELINE.items():
            with self.subTest(sequencia=acordes):
                with open(BASELINE_DIR / ('%s.json' % nome)) as arquivo:
                    esperado = set(json.load(arquivo))
                obtido = set(calcular_matches(acordes, main.musicas.values()))
                self.assertEqual(obtido, esperado)


if __name__ == '__main__':
    unittest.main()

import json
import os
import sqlite3
import tempfile
import unittest

import sequencias_db


ORIGINAIS = [
    ['Bm', 'G', 'D', 'A'],
    ['C', 'G', 'Am', 'F'],
    ['Em', 'G'],
    ['C', 'A7', 'Dm', 'G7'],
    ['Gm', 'F'],
    ['C', 'C7', 'F', 'Fm'],
]


class MusicaFalsa:

    def __init__(self, id_unico_musica, cifra):
        self.id_unico_musica = id_unico_musica
        self.cifra = cifra


class BancoSequenciasTest(unittest.TestCase):

    def setUp(self):
        self.temp_dir = tempfile.TemporaryDirectory()
        self.db_path = os.path.join(self.temp_dir.name, 'deciframe.db')
        self.musicas = [
            MusicaFalsa('m1', ['Bm', 'G', 'D', 'A']),
            MusicaFalsa('m2', ['C', 'G']),
        ]

    def tearDown(self):
        self.temp_dir.cleanup()

    def test_cria_esquema_na_versao_1(self):
        sequencias_db.init_db(self.db_path)
        with sqlite3.connect(self.db_path) as conexao:
            versao = conexao.execute('PRAGMA user_version').fetchone()[0]
            tabelas = {
                linha[0]
                for linha in conexao.execute(
                    "SELECT name FROM sqlite_master WHERE type = 'table'"
                )
            }
        self.assertEqual(versao, 1)
        self.assertTrue(
            {'sequencias', 'sequencia_matches', 'meta'} <= tabelas
        )

    def test_seed_idempotente_e_ordem_de_cadastro(self):
        primeiro = sequencias_db.inicializar(
            ORIGINAIS, self.musicas, db_path=self.db_path
        )
        segundo = sequencias_db.inicializar(
            ORIGINAIS, self.musicas, db_path=self.db_path
        )

        sequencias = sequencias_db.listar_sequencias(self.db_path)
        self.assertEqual(primeiro['semeadas'], 6)
        self.assertEqual(segundo['semeadas'], 0)
        self.assertEqual(segundo['total'], 6)
        self.assertEqual([s['id'] for s in sequencias], list(range(1, 7)))
        self.assertEqual(
            [s['acordes'] for s in sequencias],
            ORIGINAIS,
        )

    def test_seed_calcula_matches(self):
        sequencias_db.inicializar(ORIGINAIS, self.musicas, db_path=self.db_path)
        self.assertEqual(
            sequencias_db.obter_matches(1, self.db_path), {'m1'}
        )

    def test_duplicata_nao_cria_linha(self):
        sequencias_db.inicializar(ORIGINAIS, self.musicas, db_path=self.db_path)
        criada, nova = sequencias_db.criar_sequencia(
            ['Bm', 'G', 'D', 'A'], self.musicas, db_path=self.db_path
        )
        self.assertFalse(nova)
        self.assertEqual(criada['id'], 1)
        self.assertEqual(
            len(sequencias_db.listar_sequencias(self.db_path)), 6
        )

    def test_nova_sequencia_calcula_matches(self):
        sequencias_db.inicializar(ORIGINAIS, self.musicas, db_path=self.db_path)
        criada, nova = sequencias_db.criar_sequencia(
            ['C', 'G'], self.musicas, db_path=self.db_path
        )
        self.assertTrue(nova)
        self.assertEqual(
            sequencias_db.obter_matches(criada['id'], self.db_path), {'m2'}
        )

    def test_dataset_version_recalcula_matches(self):
        csv_path = os.path.join(self.temp_dir.name, 'dataset.csv')
        with open(csv_path, 'w') as arquivo:
            arquivo.write('a')

        sequencias_db.inicializar(
            ORIGINAIS,
            [MusicaFalsa('m1', ['Bm', 'G', 'D', 'A'])],
            caminho_csv=csv_path,
            db_path=self.db_path,
        )
        self.assertEqual(
            sequencias_db.obter_matches(1, self.db_path), {'m1'}
        )

        with open(csv_path, 'w') as arquivo:
            arquivo.write('conteudo maior')

        resultado = sequencias_db.inicializar(
            ORIGINAIS,
            [
                MusicaFalsa('m1', ['Bm', 'G', 'D', 'A']),
                MusicaFalsa('m3', ['Bm', 'G', 'D', 'A']),
            ],
            caminho_csv=csv_path,
            db_path=self.db_path,
        )
        self.assertEqual(resultado['recalculadas'], 6)
        self.assertEqual(
            sequencias_db.obter_matches(1, self.db_path), {'m1', 'm3'}
        )

    def test_meta_dataset_version(self):
        csv_path = os.path.join(self.temp_dir.name, 'dataset.csv')
        with open(csv_path, 'w') as arquivo:
            arquivo.write('a')

        sequencias_db.inicializar(
            ORIGINAIS, self.musicas, caminho_csv=csv_path, db_path=self.db_path
        )
        with sqlite3.connect(self.db_path) as conexao:
            valor = conexao.execute(
                "SELECT valor FROM meta WHERE chave = 'dataset_version'"
            ).fetchone()[0]
        self.assertEqual(
            valor,
            '%s:%s' % (
                os.stat(csv_path).st_size,
                os.stat(csv_path).st_mtime_ns,
            ),
        )


if __name__ == '__main__':
    unittest.main()

